//


public interface CancellationRegistryInterface {
    
    fun `acquire`(`id`: kotlin.String): RequestLease
    
    fun `cancel`(`id`: kotlin.String)
    
    fun `isCancelled`(`id`: kotlin.String): kotlin.Boolean
    
    fun `shutdown`()
    
    companion object
}

